//! ML-KEM-1024 instantiation (FIPS 203 Table 2).
//!
//! Parameters: k = 4, η₁ = η₂ = 2, dᵤ = 11, dᵥ = 5.
//! Sizes: EK_LEN = 1568, DK_LEN = 3168, CT_LEN = 1568.
//!
//! Generated by the `ml_kem_impl!` macro.

#![allow(
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    clippy::similar_names,
    dead_code
)]

crate::ml_kem_impl::ml_kem_impl! {
    k = 4;
    eta1 = 2;
    eta2 = 2;
    du = 11;
    dv = 5;
    svc_keygen = Service::MlKem1024Keygen;
    svc_expand_key = Service::MlKem1024ExpandKey;
    svc_encaps = Service::MlKem1024Encaps;
    svc_decaps = Service::MlKem1024Decaps;
    rbg_strength_bits = 256;
    pct_reason = "ML-KEM-1024 pairwise consistency";
}

#[cfg(test)]
#[allow(
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]
mod tests {
    use super::*;
    use crate::seam::ML_KEM_1024_KEYGEN_EK;
    use oxicrypt_module::{KatEntry, initialize_with_tests};

    /// Stands in for the pre-operational integrity test.
    ///
    /// A `cargo test` binary is never signed, so the real integrity test
    /// cannot pass inside one. The module requires an integrity group to
    /// initialise at all, so a test that needs a gated service declares
    /// this stub — visibly, at the call site — rather than the module
    /// offering any way to skip the requirement.
    const UNSIGNED_TEST_BINARY: &[KatEntry] = &[KatEntry {
        name: "integrity not verifiable in an unsigned test binary",
        run: || Ok(()),
    }];

    /// Initialises the module with this crate's CASTs, naming the failing
    /// CAST if one fails.
    fn ensure_initialized() {
        match initialize_with_tests(UNSIGNED_TEST_BINARY, crate::KATS) {
            Ok(()) | Err(oxicrypt_module::Error::AlreadyInitialized) => {}
            Err(e) => panic!("module failed to initialise: {e:?}"),
        }
    }

    #[test]
    fn round_trip_basic() {
        crate::test_support::start_module();
        let d = [0x42u8; 32];
        let z = [0x77u8; 32];
        let m = [0xABu8; 32];

        let (ek, dk) = keygen_internal_guarded(&d, &z).unwrap();
        let (k, ct) = encaps_internal_guarded(&ek, &m).unwrap();
        let k2 = decaps_internal_guarded(&dk, &ct).unwrap();
        assert_eq!(k, k2, "round-trip failed: shared secrets differ");
    }

    #[test]
    fn implicit_rejection_different_key() {
        crate::test_support::start_module();
        let d = [0x01u8; 32];
        let z = [0x02u8; 32];
        let m = [0x03u8; 32];

        let (ek, dk) = keygen_internal_guarded(&d, &z).unwrap();
        let (k, mut ct) = encaps_internal_guarded(&ek, &m).unwrap();
        ct[10] ^= 0xFF;
        let k_bad = decaps_internal_guarded(&dk, &ct).unwrap();
        assert_ne!(
            k, k_bad,
            "implicit rejection failed: keys match after tamper"
        );
    }

    /// A tampered ciphertext decapsulates to exactly `K̄ = J(z || c)`
    /// (FIPS 203 Algorithm 18, `J` = SHAKE-256 truncated to 32 bytes).
    ///
    /// The `assert_ne` above also passes for a selection that returns
    /// neither `K′` nor `K̄`, so this test compares against `J(z || c)`.
    #[test]
    fn implicit_rejection_matches_j_z_c() {
        use oxicrypt_xof::Shake256;
        crate::test_support::start_module();

        let d = [0x05u8; 32];
        let z = [0x06u8; 32];
        let m = [0x07u8; 32];

        let (ek, dk) = keygen_internal_guarded(&d, &z).unwrap();
        let (_k, mut ct) = encaps_internal_guarded(&ek, &m).unwrap();
        ct[42] ^= 0xA5;

        let mut j = Shake256::new_internal().unwrap();
        j.update(&z);
        j.update(&ct);
        j.finalize();
        let mut expected_k_bar = [0u8; 32];
        j.squeeze(&mut expected_k_bar).unwrap();

        let actual = decaps_internal_guarded(&dk, &ct).unwrap();
        assert_eq!(
            actual, expected_k_bar,
            "implicit rejection key must equal J(z || c) byte-exactly per FIPS 203 §7.3"
        );
    }

    #[test]
    fn different_randomness_different_keys() {
        crate::test_support::start_module();
        let d1 = [0x10u8; 32];
        let z1 = [0x20u8; 32];
        let d2 = [0x30u8; 32];
        let z2 = [0x40u8; 32];

        let (ek1, _) = keygen_internal_guarded(&d1, &z1).unwrap();
        let (ek2, _) = keygen_internal_guarded(&d2, &z2).unwrap();
        assert_ne!(ek1, ek2, "different seeds should produce different keys");
    }

    #[test]
    fn key_sizes_match_spec() {
        crate::test_support::start_module();
        assert_eq!(EK_LEN, 1568);
        assert_eq!(DK_LEN, 3168);
        assert_eq!(CT_LEN, 1568);
        assert_eq!(SHARED_SECRET_LEN, 32);
    }

    #[test]
    fn gated_api_requires_operational() {
        ensure_initialized();
        let d = [0u8; 32];
        let z = [0u8; 32];
        assert_eq!(expand_key(&d, &z), keygen_internal_guarded(&d, &z));
    }

    /// FIPS 203 §3.3: 256 bits. CTR_DRBG with AES-128 and with AES-192 are
    /// both too weak.
    #[test]
    fn with_rbg_refuses_weak_or_uninstantiated() {
        rbg_services::refuses_weak_or_uninstantiated(
            256,
            Err(Error::RbgTooWeak),
            Err(Error::RbgTooWeak),
        );
    }

    /// ACVP ML-KEM-1024 keyGen, tgId 3, tcId 51, the key-generation
    /// self-test's vector.
    #[test]
    fn expand_key_reproduces_acvp_vector() {
        use crate::cast_vectors::ml_kem_1024 as v;
        crate::test_support::start_module();
        let (ek, dk) = expand_key(&v::KEYGEN_D, &v::KEYGEN_Z).unwrap();
        assert_eq!(&ek, ML_KEM_1024_KEYGEN_EK);
        assert_eq!(dk, v::KEYGEN_DK);
    }

    #[test]
    fn encaps_refuses_noncanonical_ek() {
        input_checks::encaps_refuses_noncanonical(ML_KEM_1024_KEYGEN_EK);
    }

    /// ACVP ML-KEM-1024 encapDecap, tgId 6, tcId 96, the valid-ciphertext
    /// decapsulation self-test's vector.
    #[test]
    fn decaps_refuses_bad_ek_hash() {
        use crate::cast_vectors::ml_kem_1024 as v;
        input_checks::decaps_refuses_bad_hash(&v::DECAPS_DK, &v::DECAPS_C, &v::DECAPS_K);
    }

    /// ACVP ML-KEM-1024 encapDecap, tgId 6, tcId 97, the implicit-rejection
    /// decapsulation self-test's vector, through the public `decapsulate`.
    #[test]
    fn decaps_implicit_rejection_known_answer() {
        use crate::cast_vectors::ml_kem_1024 as v;
        input_checks::decaps_rejects_known_vector(&v::REJECT_DK, &v::REJECT_C, &v::REJECT_K);
    }

    #[test]
    fn check_encapsulation_key_verdicts() {
        input_checks::check_encapsulation_key_verdicts(ML_KEM_1024_KEYGEN_EK);
    }

    #[test]
    fn check_decapsulation_key_verdicts() {
        input_checks::check_decapsulation_key_verdicts(
            &crate::cast_vectors::ml_kem_1024::DECAPS_DK,
        );
    }

    #[test]
    fn determinism() {
        crate::test_support::start_module();
        let (ek1, dk1) = keygen_internal_guarded(&[0x5au8; 32], &[0xa5u8; 32]).unwrap();
        let (ek2, dk2) = keygen_internal_guarded(&[0x5au8; 32], &[0xa5u8; 32]).unwrap();
        assert_eq!(ek1, ek2);
        assert_eq!(dk1, dk2);

        let (k1, ct1) = encaps_internal_guarded(&ek1, &[0x3cu8; 32]).unwrap();
        let (k2, ct2) = encaps_internal_guarded(&ek2, &[0x3cu8; 32]).unwrap();
        assert_eq!(k1, k2);
        assert_eq!(ct1, ct2);
    }
}
